import{_ as e,c as r,o,ae as d}from"./chunks/framework.CFeneB-q.js";const g=JSON.parse('{"title":"PC 端 · 技术栈","description":"","frontmatter":{},"headers":[],"relativePath":"pc/technology-stack.md","filePath":"pc/technology-stack.md","lastUpdated":1789438865000}'),a={name:"pc/technology-stack.md"};function s(n,t,i,c,l,p){return o(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="pc-端-·-技术栈" tabindex="-1">PC 端 · 技术栈 <a class="header-anchor" href="#pc-端-·-技术栈" aria-label="Permalink to &quot;PC 端 · 技术栈&quot;">​</a></h1><blockquote><p>版本信息源自 <code>keystone-deliver-ui</code> / <code>e9-delivery-ui</code> 的 package.json（2026-09-16 核对）。两项目同名 <code>admin-javascript-v3</code>，核心栈一致，差异见文末。</p></blockquote><h2 id="版本矩阵" tabindex="-1">版本矩阵 <a class="header-anchor" href="#版本矩阵" aria-label="Permalink to &quot;版本矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>选型</th><th>版本</th><th>用途</th></tr></thead><tbody><tr><td>框架</td><td><a href="https://cn.vuejs.org/guide/quick-start.html" target="_blank" rel="noreferrer">Vue</a></td><td>~3.3.13</td><td>组合式 API + <code>&lt;script setup&gt;</code></td></tr><tr><td>构建</td><td><a href="https://cn.vitejs.dev/" target="_blank" rel="noreferrer">Vite</a></td><td>^4.3.9</td><td>dev / build（经 <code>pnpm start</code> 的 views-switcher 统一入口）</td></tr><tr><td>UI 库</td><td><a href="https://arco.design/vue/docs/start" target="_blank" rel="noreferrer">Arco Design Vue</a></td><td>^2.47.1</td><td><strong>组件库锁定 Arco，新页面禁止混入其他 UI 库</strong></td></tr><tr><td>状态管理</td><td><a href="https://pinia.vuejs.org/zh/" target="_blank" rel="noreferrer">Pinia</a></td><td>^2.1.4 + pinia-plugin-persist ^1.0.0</td><td>模块见 <code>src/store/modules</code>，持久化仅限白名单字段</td></tr><tr><td>路由</td><td><a href="https://router.vuejs.org/zh/" target="_blank" rel="noreferrer">Vue Router</a></td><td>^4.2.2</td><td>静态 constantRoutes + 服务端菜单动态路由</td></tr><tr><td>请求</td><td><a href="https://axios-http.com/zh/docs/intro" target="_blank" rel="noreferrer">axios</a> + axios-retry</td><td>^1.4.0 / ^4.1.0</td><td>class HttpClient 封装，见<a href="/E9-Front-Dev-Guide.io/pc/references/http-request.html">请求封装参考</a></td></tr><tr><td>国际化</td><td><a href="https://www.i18next.com/" target="_blank" rel="noreferrer">i18next</a> + i18next-vue</td><td>^25.1.1 / ^5.3.0</td><td>分域懒加载，见<a href="/E9-Front-Dev-Guide.io/pc/references/i18n-architecture.html">国际化架构</a></td></tr><tr><td>样式</td><td><a href="https://tailwindcss.com/" target="_blank" rel="noreferrer">Tailwind CSS</a> + Sass</td><td>^3.3.2 / 1.63.6</td><td>原子类 + Arco 主题覆写（arcoblue-6 改红）</td></tr><tr><td>图表</td><td><a href="https://echarts.apache.org/zh/" target="_blank" rel="noreferrer">ECharts</a></td><td>^5.4.2（+ echarts-gl ^2.0.9 大屏三维）</td><td>大屏 / 统计页</td></tr><tr><td>工具</td><td>lodash-es / dayjs / qs / mitt / crypto-js</td><td>—</td><td>—</td></tr><tr><td>业务三方</td><td>@vue-office（docx/excel/pdf/pptx）、ezuikit-js（萤石）、video.js、three、ali-oss、jspdf、html2canvas、jsencrypt、json-bigint</td><td>—</td><td>按需，勿重复引入同类库</td></tr></tbody></table><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><ul><li><strong>Node.js</strong>：项目未声明 <code>engines</code>；团队日常使用 Node 24。<strong>存量 Vue2 项目（beam-web / e9-epim）需 Node 14/16，建议 nvm 切换，勿混用</strong>（错配典型报错：node-sass、openssl）；</li><li><strong>pnpm</strong>：推荐 10.x（与指南站一致）。项目以 pnpm-lock.yaml 锁定依赖；</li><li>指南站自身的 Node v24.18.0 / pnpm 10.19.0 是<strong>文档站构建要求</strong>，各业务项目以本节与<a href="/E9-Front-Dev-Guide.io/pc/getting-started.html">快速开始</a>为准。</li></ul><h2 id="选型理由与约定" tabindex="-1">选型理由与约定 <a class="header-anchor" href="#选型理由与约定" aria-label="Permalink to &quot;选型理由与约定&quot;">​</a></h2><ol><li><strong>Pinia 而非 Vuex</strong>：Vue3 官方推荐，组合式 API 友好，TS 推断好；配合 pinia-plugin-persist 做白名单持久化（如 userInfo），token/tenantId 等敏感字段走 <code>@/utils/auth</code> 的 localStorage 封装，不进 persist。</li><li><strong>组件库锁定 Arco</strong>：全站统一 Arco Design Vue；通过 <code>vitePluginForArco</code> 按需加载样式，主题色经 less modifyVars 覆写。<strong>新页面禁止混入 Element / Ant 等其他 UI 库</strong>。</li><li><strong>unplugin-auto-import / unplugin-vue-components</strong>：vue API 与 <code>src/components</code> 下的组件免 import（生成 <code>auto-imports.d.ts</code> / <code>components.d.ts</code>，<strong>勿手改</strong>）；Arco 组件经 ArcoResolver 按需引入。</li><li><strong>vite-plugin-svg-icons</strong>：<code>src/assets/icons</code> 下的 svg 自动注册为 <code>&lt;icon-xxx&gt;</code>（symbolId <code>icon-[dir]-[name]</code>）。</li><li><strong>i18next 而非 vue-i18n（标品）</strong>：i18next 全家桶支持分域懒加载与语言探测；基座 e9-delivery-ui 仍是 vue-i18n ^9.2.2——<strong>新功能以标品的 i18next 方案为准</strong>。</li><li><strong>脚本入口统一 <code>pnpm start</code></strong>：标品没有独立的 <code>pnpm dev</code> / <code>pnpm build:pro</code> 脚本，运行与打包都经 views-switcher 选择后内部 spawn vite——这是与基座项目的显著差异。</li></ol>',8)])])}const u=e(a,[["render",s]]);export{g as __pageData,u as default};
